import * as React from "react";
import { SvgCountryIcon } from "../../assets/icons/index";
import { Tooltip } from "../tooltip";
import { IconComponentProps } from "./MpaIcon";

export interface CountryIconComponentProps
  extends Omit<IconComponentProps, "iconName"> {
  /**
   * determines the name of Icon
   */
  iconName: keyof typeof SvgCountryIcon;
}

const CountryIcon: React.FC<CountryIconComponentProps> = ({
  iconName,
  size,
  colour,
  tooltipText,
  tooltipPlacement,
}) => {
  const IconComponent = (SvgCountryIcon as Record<string, any>)[iconName];

  if (!IconComponent) {
    console.warn(`CountryIcon: icon "${iconName}" not found in SvgCountryIcon`);
    return null;
  }
  return (
    <>
      {tooltipText && tooltipText.trim().length > 0 ? (
        <Tooltip tooltipText={tooltipText} tooltipPlacement={tooltipPlacement}>
          <IconComponent size={size} color={colour} />
        </Tooltip>
      ) : (
        <IconComponent size={size} color={colour} />
      )}
    </>
  );
};

export default CountryIcon;
